CREATE INDEX reader_media_problem_identity ON reader_problems ((body::jsonb->>'media_job_identity')) WHERE finished IS NULL AND body::jsonb->>'operation'='producer:download_media';
CREATE INDEX media_subtitle_problem_lookup ON media_files(id) WHERE resource_key='youtube:subtitles';
DROP INDEX jobs_unmanaged_problems;
CREATE INDEX jobs_unmanaged_problems ON jobs(kind,item) WHERE (kind IS DISTINCT FROM 'read' OR problem_code='processor-config') AND (kind IS DISTINCT FROM 'discover' OR problem_code='processor-config') AND NOT (kind IN ('delete','feed-delete') AND coalesce(nullif(problem_code,''),'work-'||kind) IN ('delete','feed-delete','work-delete','work-feed-delete')) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-fetch')) AND (problem_code IS NOT NULL OR error IS NOT NULL) AND NOT (kind IS NOT DISTINCT FROM 'download_media' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-download_media'));
CREATE INDEX jobs_media_problem_recovery ON jobs(id) WHERE kind='download_media' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-download_media');
CREATE INDEX reader_media_problem_recovery ON reader_problems(created,id) WHERE finished IS NULL AND identity LIKE 'job:%' AND body::jsonb->>'operation' IN ('producer:download_media','producer:status') AND body::jsonb->>'code' IS NOT NULL AND body::jsonb->>'code'<>'' AND body::jsonb->>'code' NOT LIKE 'source-%' AND body::jsonb->>'code' NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch','work-download_media');
CREATE INDEX reader_media_problem_job ON reader_problems ((body::jsonb->>'media_job_id')) WHERE finished IS NULL AND body::jsonb->>'operation'='producer:download_media';
